using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionsListsList", menuName = "Data/Battle/Companions/CompanionsList Lists")]
public class CompanionsListsList : ScriptableObject
{
	[Header("Lists")]
	[SerializeField]
	private CompanionsList[] companionsLists;

	public List<CompanionData> CompanionsThatCantBePickedOnRecycleAction;

	public List<CompanionData> CompanionsThatCantBePickedOnEmulate;

	[SerializeField]
	private CompanionsList allCompanionsList;

	[Header("Progression System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private GameController gameController;

	[Header("Runtime")]
	public List<string> DiscoveredSentinels = new List<string>();

	public CompanionsList[] CompanionsLists => companionsLists;

	public CompanionsList GetCompanionsList(Character character)
	{
		for (int i = 0; i < companionsLists.Length; i++)
		{
			if (companionsLists[i].Character == character)
			{
				return companionsLists[i];
			}
		}
		return null;
	}

	public CompanionData GetCompanionData(string companionName)
	{
		CompanionData companionData = null;
		for (int i = 0; i < companionsLists.Length; i++)
		{
			companionData = companionsLists[i].GetCompanionData(companionName, logError: false);
			if (companionData != null)
			{
				return companionData;
			}
		}
		return companionData;
	}

	public void LoadDiscoveredSentinels()
	{
		companionsLists.InteractThroughItems(delegate(CompanionsList item)
		{
			item.Companions.RemoveNullObjects();
		});
		allCompanionsList.Companions.RemoveNullObjects();
		saveSystem.LoadDiscoveredSentinels();
		List<CompanionData> list = new List<CompanionData>();
		for (int i = 0; i < companionsLists.Length; i++)
		{
			list.AddRange(companionsLists[i].Companions);
		}
		for (int j = 0; j < list.Count; j++)
		{
			if (list[j].CompendiumItemState != CompendiumItemState.Locked)
			{
				if (DiscoveredSentinels.Contains(list[j].name))
				{
					list[j].SetCompendiumItemState(CompendiumItemState.Discovered);
				}
				else
				{
					list[j].SetCompendiumItemState(CompendiumItemState.Undiscovered);
				}
			}
		}
	}

	public void SentinelsDiscovered(List<CompanionData> companionDatas)
	{
		if (gameController.IsDemo)
		{
			return;
		}
		for (int i = 0; i < companionDatas.Count; i++)
		{
			if (companionDatas[i].CompendiumItemState != 0)
			{
				companionDatas[i].SetCompendiumItemState(CompendiumItemState.Discovered);
				DiscoveredSentinels.Add(companionDatas[i].name);
			}
		}
		saveSystem.SaveDiscoveredSentinels(saveAndStoreCache: true);
	}

	public void SetAllSentinelsDiscovered()
	{
		List<CompanionData> list = new List<CompanionData>();
		for (int i = 0; i < companionsLists.Length; i++)
		{
			list.AddRange(companionsLists[i].Companions);
		}
		SentinelsDiscovered(list);
	}

	public void SetAllCompanionsToUndiscoveredOrLocked()
	{
		SetAllCompanionsToUndiscovered();
		DiscoveredSentinels.Clear();
		saveSystem.SaveDiscoveredSentinels(saveAndStoreCache: true);
	}

	public void SetAllCompanionsToUndiscovered()
	{
		for (int i = 0; i < companionsLists.Length; i++)
		{
			List<CompanionData> companions = companionsLists[i].Companions;
			for (int j = 0; j < companions.Count; j++)
			{
				companions[j].SetCompendiumItemState(CompendiumItemState.Undiscovered);
			}
		}
	}

	public float GetSentinelDiscoveredAmount()
	{
		float num = 0f;
		for (int i = 0; i < companionsLists.Length; i++)
		{
			List<CompanionData> companions = companionsLists[i].Companions;
			for (int j = 0; j < companions.Count; j++)
			{
				if (companions[j].CompendiumItemState == CompendiumItemState.Discovered)
				{
					num += 1f;
				}
			}
		}
		return num;
	}

	public float GetSentinelTotal()
	{
		float num = 0f;
		for (int i = 0; i < companionsLists.Length; i++)
		{
			_ = companionsLists[i].Companions;
			num += (float)companionsLists[i].Companions.Count;
		}
		return num;
	}

	public float GetCharacterSentinelDiscoveredAmount(Character character)
	{
		float num = 0f;
		List<CompanionData> companions = GetCompanionsList(character).Companions;
		for (int i = 0; i < companions.Count; i++)
		{
			if (companions[i].CompendiumItemState == CompendiumItemState.Discovered)
			{
				num += 1f;
			}
		}
		return num;
	}

	public void ClearModdedCompanions()
	{
		companionsLists.InteractThroughItems(delegate(CompanionsList item)
		{
			item.ClearModdedCompanions();
		});
	}
}
